{
  "slug": "syncora-company-missing",
  "title": "Why a Tally Company May Be Missing in Syncora",
  "description": "Trace a missing company through the account, selected TallyPrime company and most recent connector run.",
  "category": "Sync troubleshooting",
  "sections": [
    {
      "heading": "Confirm which account is open",
      "body": "Check the account currently signed in on the website or Android app and the account used on the Windows connector. If a colleague has access to a different company or account, their view is not evidence that your account should see it."
    },
    {
      "heading": "Check the intended company on the PC",
      "body": "On the accounting computer, confirm that the intended company is the one selected for sync. Read the connector result for the last run and record any error. If it has not succeeded for that company, resolve the connector issue before repeating the dashboard search."
    },
    {
      "heading": "Send a focused report when both checks pass",
      "body": "Include the company name as shown in TallyPrime, the time of the successful run and the connector version. Describe which account should have access and where you looked for the company. Share private account details only through your normal support channel."
    }
  ],
  "relatedPaths": [
    "/guides/tally-sync-troubleshooting",
    "/support"
  ]
}
